package policy; public final class ShadowFinding{private final int shadowedIndex;private final int byIndex;private final String reason;public ShadowFinding(int shadowedIndex,int byIndex,String reason){this.shadowedIndex=shadowedIndex;this.byIndex=byIndex;this.reason=reason;}public int shadowedIndex(){return shadowedIndex;}public int byIndex(){return byIndex;}public String reason(){return reason;}public String toString(){return"rule "+shadowedIndex+" shadowed by "+byIndex+": "+reason;}}
